                values = decoded
            end
        end
    end)
    if not ok then
        log(S(770) .. filePath .. S(358) .. tostring(err))
    end
end
local function save()
    local ok, err = pcall(function()
        ensureFolders()
        writefile(filePath, HttpService:JSONEncode(values))
