return function(import)
local gameApi = import(S(638))(import)
local log = import(S(405))
local checkInterval = 3
local minItemsToCollect = 100
local autoChest = {}
local enabled = false
local busy = false
local lastAttempt = 0
local lastReported = nil
function autoChest.SetEnabled(state)
    if state == enabled then
        return
    end
    enabled = state
    lastReported = nil
    if enabled then
        lastAttempt = 0
        log(S(235) .. minItemsToCollect .. S(255))
    else
        log(S(342))
    end
end
function autoChest.IsEnabled()
    return enabled
end
function autoChest.IsBusy()
    return busy
end
function autoChest.SetMinItems(value)
    minItemsToCollect = math.max(value, 1)
end
function autoChest.SetCheckInterval(seconds)
    checkInterval = math.max(seconds, 1)
end
local function threshold()
    local capacity = gameApi.ChestCapacity()
    if capacity and capacity > 0 then
        return math.min(minItemsToCollect, capacity)
    end
    return minItemsToCollect
end
function autoChest.HasWork()
    if not gameApi.ChestHasItems() then
        return false
    end
    local count = gameApi.ChestCount()
    return count ~= nil and count >= threshold()
end
function autoChest.Step()
    if not enabled or busy then
        return
    end
    local now = tick()
    if now - lastAttempt < checkInterval then
        return
    end
    lastAttempt = now
    local count = gameApi.ChestCount()
    if not count then
        if lastReported ~= S(55) then
            log(S(181))
            lastReported = S(716)
        end
        return
    end
    if not gameApi.ChestHasItems() then
        if lastReported ~= S(753) then
            log(S(640))
            lastReported = S(206)
        end
        return
    end
    local want = threshold()
    if count < want then
        if lastReported ~= S(297) then
            local capacity = gameApi.ChestCapacity()
            log(S(105) .. count .. S(487) .. want .. S(49)
                .. (capacity and (S(719) .. capacity .. S(603)) or S(662)))
            lastReported = S(464)
        end
        return
    end
    lastReported = nil
    busy = true
    task.spawn(function()
        gameApi.TakeChest()
        task.wait(0.5)
        local after = gameApi.ChestCount()
        if after and after < count then
            log(S(78) .. count .. S(576) .. after .. S(362))
        else
            log(S(106) .. count
                .. S(526) .. tostring(after) .. S(118))
        end
        busy = false
    end)
end
return autoChest
end
