modules[S(493)] = function()
return function(import)
    local createWindow = import(S(232))(import)
    local i18n = import(S(364))
    local antiAfk = import(S(134))(import)
    local buildEnv = import(S(137))
    local scheduler = import(S(183))(import)
    local config = import(S(123))(import)
    local log = import(S(10))
    local window = createWindow({
        Subtitle = S(775),
    })
    local function persistentToggle(card, key, apply, default)
        local saved = config.Get(key, default or false)
        card:AddToggle(saved, function(state)
            config.Set(key, state)
            apply(state)
        end)
        apply(saved)
    end
    local function persistentSlider(tab, title, subtitle, min, max, key, default, apply, suffix)
        local saved = config.Get(key, default)
        tab:AddSlider(title, subtitle, min, max, saved, function(value)
            config.Set(key, value)
            apply(value)
        end, suffix)
        apply(saved)
    end
    local function persistentSegmented(tab, options, values, key, default, apply)
        local savedIndex = config.Get(key, default)
        tab:AddSegmented(options, savedIndex, function(index)
            config.Set(key, index)
            apply(values[index])
        end)
        apply(values[savedIndex] or values[default])
    end
    local autoMine = import(S(654))(import)
    local autoPlace = import(S(180))(import)
    local autoChest = import(S(158))(import)
    local autoSell = import(S(664))(import)
    local autoUpgrade = import(S(196))(import)
    local autoResearch = import(S(559))(import)
    local autoClaim = import(S(311))(import)
    local gameApi = import(S(702))(import)
    scheduler.RegisterStandalone(S(352), autoMine.Step, autoMine.IsEnabled)
    scheduler.RegisterExclusive(S(67), autoChest.Step, autoChest.IsEnabled, autoChest.IsBusy, autoChest.HasWork)
    scheduler.RegisterExclusive(S(659), autoPlace.Step, autoPlace.IsEnabled, autoPlace.IsBusy, autoPlace.HasWork)
    scheduler.RegisterExclusive(S(402), autoUpgrade.Step, autoUpgrade.IsEnabled, autoUpgrade.IsBusy, autoUpgrade.HasWork)
    scheduler.RegisterExclusive(S(645), autoResearch.Step, autoResearch.IsEnabled, autoResearch.IsBusy, autoResearch.HasWork)
    scheduler.RegisterExclusive(S(59), autoClaim.Step, autoClaim.IsEnabled, autoClaim.IsBusy, autoClaim.HasWork)
    autoSell.SetHoldWhile(function()
        return autoPlace.IsEnabled() and autoPlace.HasWork()
    end)
    local sellMaxWait = config.Get(S(305), 20)
    scheduler.RegisterExclusive(S(332), autoSell.Step, autoSell.IsEnabled, autoSell.IsBusy, autoSell.HasWork, sellMaxWait)
    scheduler.Start()
    local farmTab = window:AddTab(S(646), S(740))
    persistentToggle(farmTab:AddCard(
        S(40),
        S(472)
    ), S(326), autoMine.SetEnabled)
    persistentSlider(farmTab, S(15), S(258),
        1, 30, S(584), 5, autoMine.SetCyclesPerSecond, S(37))
    persistentSlider(farmTab, S(268), S(611),
        1, 10, S(260), 1, autoMine.SetClicksPerCycle, S(581))
    persistentToggle(farmTab:AddCard(
        S(523),
        S(192)
    ), S(731), autoPlace.SetEnabled)
    persistentSlider(farmTab, S(492), S(699),
        1, 60, S(43), 3, autoPlace.SetCheckInterval, S(447))
    persistentToggle(
        farmTab:AddCard(S(539),
            S(363)),
        S(315), autoPlace.SetUpgradeWeakMiners
    )
    persistentToggle(farmTab:AddCard(
        S(587),
        S(498)
    ), S(387), autoChest.SetEnabled)
    persistentSlider(farmTab, S(431), S(761),
        50, 3000, S(168), 100, autoChest.SetMinItems, S(370))
    persistentSlider(farmTab, S(409), S(656),
        1, 60, S(637), 3, autoChest.SetCheckInterval, S(522))
    persistentToggle(farmTab:AddCard(
        S(359),
        S(244)
    ), S(648), autoSell.SetEnabled)
    persistentSlider(farmTab, S(90), S(48),
        5, 300, S(204), 20, autoSell.SetCheckInterval, S(562))
    farmTab:AddSlider(S(111),
        S(721),
        5, 120, sellMaxWait, function(value)
            config.Set(S(339), value)
        end, S(588))
    persistentToggle(farmTab:AddCard(
        S(270),
        S(724)
    ), S(148), autoUpgrade.SetEnabled)
    persistentSlider(farmTab, S(495), S(23),
        5, 300, S(178), 20, autoUpgrade.SetInterval, S(210))
    persistentSlider(farmTab, S(632), S(435),
        1, 20, S(241), 5, autoUpgrade.SetMaxPerPass, S(146))
    persistentSegmented(
        farmTab,
        { S(742), S(215), S(287), S(335) },
        { S(238), S(771), S(607), S(461) },
        S(46), 1, autoUpgrade.SetPriority
    )
    persistentSlider(farmTab, S(143), S(3),
        0, 500, S(20), 0,
        function(value) autoUpgrade.SetKeepMoney(value * 1e6) end, S(249))
    persistentToggle(
        farmTab:AddCard(S(649),
            S(126)),
        S(569), autoUpgrade.SetBuyPickaxe, true
    )
    local pickaxes = gameApi.GetPickaxes()
    local pickaxeLabels = {}
    local highestIndex = 0
    for _, pickaxe in ipairs(pickaxes) do
        pickaxeLabels[pickaxe.index] = pickaxe.name .. S(751) .. pickaxe.multiplier .. S(290)
        highestIndex = math.max(highestIndex, pickaxe.index)
    end
    if highestIndex > 0 then
        local pickaxeCard
        local function describePick(index)
            if index == 0 then
                return S(279)
            end
            return S(124) .. index .. S(165) .. (pickaxeLabels[index] or S(725))
        end
        local savedPick = config.Get(S(324), 0)
        pickaxeCard = farmTab:AddSlider(
            S(29),
            describePick(savedPick),
            0, highestIndex, savedPick,
            function(value)
                config.Set(S(630), value)
                autoUpgrade.SetPickaxeTarget(value)
                pickaxeCard:SetSubtitle(describePick(value))
            end,
            S(579)
        )
        autoUpgrade.SetPickaxeTarget(savedPick)
    end
    persistentToggle(
        farmTab:AddCard(S(152),
            S(552)),
        S(306), autoUpgrade.SetLimitPickaxesToHolders, true
    )
    persistentToggle(
        farmTab:AddCard(S(613),
            S(509)),
        S(100), autoUpgrade.SetEquipPickaxes, true
    )
    persistentToggle(
        farmTab:AddCard(S(132),
            S(410)),
        S(236), autoUpgrade.SetRollMutations
    )
    persistentSlider(farmTab, S(175), S(437),
        1, 20, S(729), 2, autoUpgrade.SetMutationTarget, S(774))
    persistentSlider(farmTab, S(553), S(403),
        0, 500, S(36), 0,
        function(value) autoUpgrade.SetMutationBudget(value * 1e6) end, S(250))
    persistentToggle(farmTab:AddCard(
        S(325),
        S(289)
    ), S(712), autoResearch.SetEnabled)
    persistentSlider(farmTab, S(653), S(199),
        10, 600, S(354), 30, autoResearch.SetCheckInterval, S(231))
    persistentSlider(farmTab, S(782), S(605),
        1, 20, S(565), 5, autoResearch.SetMaxPerPass, S(436))
    persistentSlider(farmTab, S(170), S(621),
        0, 500, S(207), 0,
        function(value) autoResearch.SetKeepMoney(value * 1e6) end, S(641))
    persistentToggle(
        farmTab:AddCard(S(689),
            S(156)),
        S(767), autoResearch.SetBuyZones, true
    )
    persistentToggle(
        farmTab:AddCard(S(567),
            S(454)),
        S(486), autoResearch.SetBuyCore, true
    )
    persistentSegmented(
        farmTab,
        { S(527), S(715) },
        { true, false },
        S(671), 1, autoResearch.SetCheapestFirst
    )
    persistentToggle(farmTab:AddCard(
        S(323),
        S(54)
    ), S(96), autoClaim.SetEnabled)
    persistentSlider(farmTab, S(476), S(558),
        5, 300, S(201), 30, autoClaim.SetCheckInterval, S(4))
    persistentSlider(farmTab, S(521), S(222),
        1, 30, S(162), 10, autoClaim.SetMaxPerPass, S(647))
    local stopDebug = nil
    if buildEnv.IsDev then
        stopDebug = import(S(475))(import)(window, {
            Toggle = persistentToggle,
            Slider = persistentSlider,
        })
    end
    local settingsTab = window:AddTab(S(395), S(337))
    persistentToggle(
        settingsTab:AddCard(S(575), S(573)),
        S(424),
        antiAfk.SetEnabled
    )
    local savedScale = config.Get(S(488), 100)
    settingsTab:AddSlider(S(17), S(529), 50, 150, savedScale, function(value)
        config.Set(S(286), value)
        window:SetScale(value)
    end)
    window:SetScale(savedScale)
    local savedLanguage = config.Get(S(416), 1)
    settingsTab:AddSegmented({ S(616), S(633), S(586) }, savedLanguage, function(index, value)
        local code = ({ S(680), S(161), S(510) })[index]
        config.Set(S(256), index)
        i18n.SetLanguage(code)
    end)
    i18n.SetLanguage(({ S(344), S(723), S(543) })[savedLanguage] or S(357))
    log(S(187) .. config.Path())
    window:OnDestroy(function()
        scheduler.Stop()
        autoMine.SetEnabled(false)
        autoPlace.SetEnabled(false)
        autoChest.SetEnabled(false)
        antiAfk.SetEnabled(false)
        autoSell.SetEnabled(false)
        autoUpgrade.SetEnabled(false)
        autoResearch.SetEnabled(false)
        autoClaim.SetEnabled(false)
        if stopDebug then
            stopDebug()
        end
    end)
end
end
modules[S(243)] = function()
return {
    [79389059854988] = S(535),
}
end
import(S(675))(import)
